        })
    }

    macro_rules! assert_approx_eq {
        ($l:expr, $r:expr) => {
            assert!(($l - $r).abs() < Abs::pt(0.1), "{:?} ≉ {:?}", $l, $r);
        };
    }

    #[track_caller]
    fn assert_jump_eq(jump: Option<Jump>, expected: Option<Jump>) {
        if let (Some(Jump::Position(pos)), Some(Jump::Position(expected))) =
